import { createHash } from "node:crypto";
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const packageDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const repositoryDir = path.resolve(packageDir, "../..");
const sdkSourceDir = path.join(repositoryDir, "packages/sdk/src");
const manifest = JSON.parse(await readFile(path.join(packageDir, "package.json"), "utf8"));
const sdkDocsRevision = await hashTree(sdkSourceDir);
const output = [
  "/** This file is generated from package.json and SDK source by scripts/generate-version.mjs. */",
  `export const VERSION = ${JSON.stringify(manifest.version)};`,
  `export const SDK_DOCS_REVISION = ${JSON.stringify(sdkDocsRevision)};`,
  "",
].join("\n");
const docsOutput = [
  "/** This file is generated by packages/create-stellaris-mod/scripts/generate-version.mjs. */",
  `export const SDK_DOCS_REVISION = ${JSON.stringify(sdkDocsRevision)};`,
  "",
].join("\n");

const generatedPath = path.join(packageDir, "src/generated/package-version.ts");
const docsGeneratedPath = path.join(
  repositoryDir,
  "packages/docs-site/lib/generated/sdk-docs-revision.ts"
);
if (process.argv.includes("--check")) {
  for (const [generatedFile, expected] of [
    [generatedPath, output],
    [docsGeneratedPath, docsOutput],
  ]) {
    const actual = await readFile(generatedFile, "utf8");
    if (actual !== expected) {
      throw new Error(
        `${path.relative(process.cwd(), generatedFile)} is stale. Run npm run generate:version ` +
          "in packages/create-stellaris-mod and commit the result."
      );
    }
  }
} else {
  await writeFile(generatedPath, output);
  await writeFile(docsGeneratedPath, docsOutput);
}

async function hashTree(root) {
  const files = await listFiles(root);
  const hash = createHash("sha256");
  for (const file of files) {
    hash.update(path.relative(root, file).split(path.sep).join("/"));
    hash.update("\0");
    hash.update(await readFile(file));
    hash.update("\0");
  }
  return hash.digest("hex");
}

async function listFiles(root) {
  const files = [];
  for (const entry of await readdir(root, { withFileTypes: true })) {
    const entryPath = path.join(root, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await listFiles(entryPath)));
    } else if (entry.isFile()) {
      files.push(entryPath);
    }
  }
  return files.sort();
}
